// barWidthPct is a ranked bar's share of the longest bar.
func barWidthPct(n, top int64) string {
	if top <= 0 {
		return "0%"
	}
	return strconv.FormatFloat(float64(n)/float64(top)*100, 'f', 2, 64) + "%"
}

